function calculateProductPayout(product={}){
 const price=Math.max(0,Number(product.birmarket_price)||0);
 const category=BIRM_CATEGORIES.find(x=>x.name===String(product.category||'').trim());
 if(!category||price<=0)return {ready:false};
 const weight=Math.max(0,Number(product.weight_kg)||0);
 const dm=String(product.notes||'').match(/(?:ölçülər|olculer|dimensions)\s*[:\-]?\s*(\d+(?:[.,]\d+)?)\s*(?:x|×|\*)\s*(\d+(?:[.,]\d+)?)\s*(?:x|×|\*)\s*(\d+(?:[.,]\d+)?)/i);
 const dims=dm?dm.slice(1).map(v=>Number(v.replace(',','.'))):null;
 const hasDims=!!dims&&dims.every(v=>Number.isFinite(v)&&v>0);
 const volume=hasDims?dims[0]*dims[1]*dims[2]/1000000:null;
 const side=hasDims?Math.max(...dims)/100:null;
 let cls=0;
 if(weight>60||(volume!==null&&volume>0.46))cls=3;
 else if(weight>30||(volume!==null&&volume>0.12)||(side!==null&&side>1.2))cls=2;
 else if(weight>1||(volume!==null&&volume>0.0038)||(side!==null&&side>0.35))cls=1;
 const logistics=price<10?0:([[1,2],[2,5],[7,11],[12,15]][cls][price>=50?1:0]);
 const categoryFee=price*Number(category.rate)/100;
 const bankFee=price*1.5/100;
 const payout=Math.round((price-categoryFee-bankFee-logistics+Number.EPSILON)*100)/100;
 return {ready:true,rate:Number(category.rate),categoryFee,bankFee,logistics,parcelName:['Paket','Standart','KQT','KQT+'][cls],payout,price};
}

const ORDER_BANK_RATES={card:1.5,credit:1.5,installment:{3:1.5,6:4,9:5,12:6,18:8.2,24:10.2}};
const normalizeTariff=s=>String(s||'').toLocaleLowerCase('az').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
function getProductTariff(product){
 const raw=String(product?.category||'').trim();
 const direct=BIRM_CATEGORIES.find(x=>x.name===raw);
 if(direct)return direct;
 const n=normalizeTariff(raw);
 const aliases={
  'agilli saatlar':'Smart saatlar və fitnes qolbaqları',
  'qulaqliqlar':'Qulaqlıqlar və qarnituralar',
  'proyektorlar':'Uşaq gecə lampaları, proyektorlar'
 };
 const alias=aliases[n];
 if(alias){const hit=BIRM_CATEGORIES.find(x=>x.name===alias);if(hit)return hit}
 return BIRM_CATEGORIES.find(x=>normalizeTariff(x.name)===n)||
  BIRM_CATEGORIES.find(x=>normalizeTariff(x.name).includes(n)||n.includes(normalizeTariff(x.name)));
}
function calculateOrderCosts(product,quantity,payment='card',months=3){
 const qty=Math.max(1,Number(quantity)||1),price=Math.max(0,Number(product?.birmarket_price)||0),total=price*qty;
 const category=getProductTariff(product);
 if(!category||!price)return {ready:false,category,total};
 const weight=Math.max(0,Number(product?.weight_kg)||0)*qty;
 const dm=String(product?.notes||'').match(/(?:ölçülər|olculer|dimensions)\s*[:\-]?\s*(\d+(?:[.,]\d+)?)\s*(?:x|×|\*)\s*(\d+(?:[.,]\d+)?)\s*(?:x|×|\*)\s*(\d+(?:[.,]\d+)?)/i);
 const dims=dm?dm.slice(1).map(v=>Number(v.replace(',','.'))):null;
 const hasDims=!!dims&&dims.every(v=>Number.isFinite(v)&&v>0);
 const volume=hasDims?dims[0]*dims[1]*dims[2]/1000000:null;
 const side=hasDims?Math.max(...dims)/100:null;
 let cls=0;
 if(weight>60||(volume!==null&&volume*qty>0.46))cls=3;
 else if(weight>30||(volume!==null&&volume*qty>0.12)||(side!==null&&side>1.2))cls=2;
 else if(weight>1||(volume!==null&&volume*qty>0.0038)||(side!==null&&side>0.35))cls=1;
 const logistics=total<10?0:([[1,2],[2,5],[7,11],[12,15]][cls][total>=50?1:0]);
 const bankRate=payment==='installment'?(ORDER_BANK_RATES.installment[Number(months)]||1.5):(ORDER_BANK_RATES[payment]||1.5);
 const commission=Math.round((total*Number(category.rate)/100+Number.EPSILON)*100)/100;
 const bank=Math.round((total*bankRate/100+Number.EPSILON)*100)/100;
 const payout=Math.round((total-commission-bank-logistics+Number.EPSILON)*100)/100;
 return {ready:true,category,rate:Number(category.rate),total,commission,logistics,bankRate,bank,payout,parcelName:['Paket','Standart','KQT','KQT+'][cls]};
}

