 {tab==='cancel'&&<><div className="toolbar"><div><h2>Ləğv edilənlər</h2><p>Ləğv səbəbləri, məhsul məlumatları və təkrar ləğv edən müştərilərin arxivi.</p></div></div><div className="cancel-summary"><div className="cancel-metric"><small>Ümumi ləğv qeydləri</small><b>{currentMonthCancellationCount}</b><span>{new Date().toLocaleDateString('az-AZ',{month:'long',year:'numeric'})} ayının unikal sifariş hadisələri</span></div><div className="cancel-metric warning"><small>Təkrar ləğv edən müştərilər</small><b>{repeatedCustomerDetails.length}</b><span>Ən azı 2 ləğv hadisəsi</span></div></div><section className="repeat-section"><div className="repeat-section-head"><div><span className="repeat-kicker">MÜŞTƏRİ İZLƏMƏSİ</span><h3>Təkrar ləğv edən müştərilər</h3><p>Ad-soyada görə qruplaşdırılır. Eyni sifarişdə müxtəlif məhsullar bir hadisədir, eyni məhsulun təkrar ləğv qeydləri isə ayrıca sayılır.</p></div><strong className="repeat-total">{repeatedCustomerDetails.length} müştəri</strong></div>{repeatedCustomerDetails.length?<><div className="repeat-customer-list">{repeatedCustomerDetails.map(customer=><button type="button" className={'repeat-customer-card '+(selectedRepeatCustomer===customer.key?'active':'')} key={customer.key} onClick={()=>SR(selectedRepeatCustomer===customer.key?'':customer.key)}><span className="repeat-avatar">{customer.name.split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase()}</span><span className="repeat-customer-card-info"><b>{customer.name}</b><small>{customer.events.length} ləğv hadisəsi · {customer.events.reduce((sum,event)=>sum+event.items.reduce((n,item)=>n+(Number(item.quantity)||1),0),0)} ədəd məhsul</small></span><span className="repeat-count">{customer.events.length} dəfə</span><span className="repeat-card-action">{selectedRepeatCustomer===customer.key?'Bağla':'Detallara bax'}</span></button>)}</div>{(()=>{const customer=repeatedCustomerDetails.find(item=>item.key===selectedRepeatCustomer);return customer?<section className="repeat-customer-detail"><div className="repeat-detail-head"><div><span className="repeat-kicker">MÜŞTƏRİ LƏĞV TARİXÇƏSİ</span><h4>{customer.name}</h4><p>{customer.events.length} ləğv hadisəsi · {customer.events.reduce((sum,event)=>sum+event.items.reduce((n,item)=>n+(Number(item.quantity)||1),0),0)} ədəd məhsul</p></div><button type="button" className="outline" onClick={()=>SR('')}>Bağla</button></div><div className="repeat-events">{customer.events.map((event,index)=>{const order=data.orders.find(item=>item.id===event.orderId);return <div className="repeat-event" key={event.key}><div className="repeat-event-top"><b>Ləğv #{customer.events.length-index}</b><span>{dt(event.cancelledAt)}</span></div>{order&&<div className="repeat-order-meta"><span>Sifariş: <b>#{order.order_number||String(order.id).slice(0,8).toUpperCase()}</b></span><span>Daxilolma: <b>{dt(order.ordered_at)}</b></span><span>Mənbə: <b>{order.source||'—'}</b></span><span>Ödəniş: <b>{order.payment_status==='paid'?'Təsdiqlənib':'Gözləyir'}</b></span></div>}<div className="repeat-products">{event.items.map((item,itemIndex)=><div className="repeat-product" key={item.id||itemIndex}>{item.product_image_url?<img src={item.product_image_url} alt="" loading="lazy"/>:<div className="repeat-product-placeholder"><Boxes size={15}/></div>}<div className="repeat-product-info"><b>{item.product_name||'Məhsul adı yoxdur'}</b><small>Miqdar: {item.quantity||1} ədəd</small><small>Səbəb: {item.cancellation_reason||'Səbəb qeyd edilməyib'}</small></div></div>)}</div></div>})}</div></section>:null})()}</>:<div className="repeat-empty"><span>✓</span><b>Təkrar ləğv edən müştəri yoxdur</b><p>Müştəri ən azı iki ləğv hadisəsi etdikdə burada görünəcək.</p></div>}</section><section className="panel cancellation-archive"><div className="cancellation-archive-head"><div><h3>Bütün ləğv qeydləri</h3><p>Seçdiyin günlər üzrə ləğv tarixçəsi. Təkrar müştəri kartları bu filtrdən asılı deyil.</p></div><span>{filteredCancellationRows.length} qeyd</span></div><div className="cancel-date-filter"><div className="cancel-date-add"><label htmlFor="cancel-day">Müddət</label><div><input id="cancel-day" type="date" value={cancelDateDraft} onChange={e=>CDD(e.target.value)}/><button className="primary" type="button" disabled={!cancelDateDraft||cancelDates.includes(cancelDateDraft)} onClick={()=>CD(old=>[...old,cancelDateDraft].sort())}><CheckCircle2 size={15}/> Seç</button></div></div></div><div className="month-filter cancel-month-filter"><div className="month-filter-head"><div><b>Seçilmiş tarixlər</b><small>Gün, ay və ili seçib “Seç” düyməsinə bas. Bir neçə günü birlikdə göstərə bilərsən.</small></div><span>{cancelDates.length} gün</span></div><div className="month-chips">{cancelDates.map(d=><span className="month-chip cancel-day-chip" key={'d'+d}>{new Date(d+'T12:00:00').toLocaleDateString('az-AZ',{day:'numeric',month:'long',year:'numeric'})}<button type="button" aria-label="Günü çıxart" onClick={()=>CD(old=>old.filter(x=>x!==d))}>×</button></span>)}{!cancelDates.length&&<span className="month-empty">Tarix seçilməyib. Bütün ləğv qeydləri göstərilir.</span>}</div><div className="cancel-filter-actions"><button type="button" className="outline" onClick={()=>CD([])} disabled={!cancelDates.length}>Hamısını təmizlə</button></div></div><div className="record-card-list cancellation-card-list">{filteredCancellationRows.map(x=>{const order=data.orders.find(item=>item.id===x.order_id);return <article className="record-card" key={x.id}><div className="record-card-media">{x.product_image_url?<img src={x.product_image_url} alt={x.product_name||'Məhsul'} loading="lazy"/>:<span className="record-card-placeholder"><Boxes size={28}/></span>}<span className="record-card-status is-bad">Ləğv edilib</span></div><div className="record-card-body"><div className="record-card-heading"><div><small>SİFARİŞ №</small><h3>#{order?.order_number||String(x.order_id||'').slice(0,8).toUpperCase()||'—'}</h3></div><strong className="record-card-quantity">{x.quantity||1} ədəd</strong></div><h4 className="record-card-product-title">{x.product_name||'Məhsul adı yoxdur'}</h4><div className="record-card-details"><div><small>Müştəri</small><b>{x.customer_name||'—'}</b></div><div><small>Ləğv tarixi / saatı</small><b>{dt(x.cancelled_at)}</b></div><div><small>Ləğv səbəbi</small><b>{x.cancellation_reason||'Səbəb qeyd edilməyib'}</b></div><div><small>Sifariş mənbəyi</small><b>{order?.source||'—'}</b></div></div></div></article>})}{!filteredCancellationRows.length&&<p className="empty">Seçilmiş tarixlər üzrə ləğv qeydi yoxdur. Başqa gün seç və ya filtri təmizlə.</p>}</div></section></>}{tab==='reports'&&<MonthlyReportsPanel orders={data.orders} adjustedSales={adjustedSales} products={data.products}/>}
  {tab==='customers'&&<><div className="toolbar"><div><h2>Müştəri analitikası</h2><p>Ən çox alış edənlər, təkrar müştərilər və alış tarixçəsi.</p></div></div><CustomerAnalyticsPanel orders={data.orders} sales={adjustedSales} returns={data.returns}/></>}
