 {tab==='analytics'&&(()=>{const now=new Date(),cur=monthKey(now),prevDate=new Date(now.getFullYear(),now.getMonth()-1,1),prev=monthKey(prevDate),paidOrderIds=new Set(data.orders.filter(x=>x.delivery_status==='delivered'&&x.payment_status==='paid'&&!!x.paid_at).map(x=>x.id)),current=adjustedSales.filter(x=>!!x.paid_at&&paidOrderIds.has(x.order_id)&&monthKey(x.paid_at)===cur),previous=adjustedSales.filter(x=>!!x.paid_at&&paidOrderIds.has(x.order_id)&&monthKey(x.paid_at)===prev),curProfit=current.reduce((n,x)=>n+Number(x.net_profit||0),0),prevProfit=previous.reduce((n,x)=>n+Number(x.net_profit||0),0),revenue=list=>list.reduce((n,x)=>n+Number(x.transferred_amount||0)*Number(x.quantity||0),0);return <><div className="toolbar"><div><h2>Ətraflı analitika</h2><p>Bu ayın nəticələrini əvvəlki ayla müqayisə et.</p></div></div><div className="stats"><Stat I={ShoppingCart} label="Bu ay satış sayı" value={current.length} note={'Ötən ay: '+previous.length}/><Stat I={Boxes} label="Az qalan məhsullar" value={low.length} note="Anbar xəbərdarlıqları"/></div><section className="panel"><h3>Ən çox qazanc gətirən məhsullar</h3><div className="tablewrap"><table><thead><tr><th>Məhsul</th><th>Satılan miqdar</th><th>Dövriyyə</th><th>Xalis mənfəət</th></tr></thead><tbody>{[...current.reduce((map,x)=>{const key=x.product_id||x.product_name;const item=map.get(key)||{key,name:x.product_name,quantity:0,revenue:0,profit:0};item.quantity+=Number(x.quantity||0);item.revenue+=Number(x.transferred_amount||0)*Number(x.quantity||0);item.profit+=Number(x.net_profit||0);map.set(key,item);return map},new Map()).values()].sort((a,b)=>b.profit-a.profit).slice(0,10).map(x=><tr key={x.key}><td>{x.name}</td><td>{x.quantity}</td><td>{fmt(x.revenue)}</td><td className={x.profit>=0?'good':'bad'}>{fmt(x.profit)}</td></tr>)}</tbody></table>{!current.length&&<p className="empty">Bu ay üçün satış məlumatı yoxdur.</p>}</div></section></>})()}
 {tab==='ai'&&<AIManager inventory={data.products.map(({id,name,sku,category,cost_price,sale_price,stock_qty,low_stock_threshold,is_active})=>({id,name,sku,category,cost_price,sale_price,stock_qty,low_stock_threshold,is_active}))} orders={data.orders.map(item=>({delivery_status:item.delivery_status,order_items:(item.order_items||[]).map(line=>({product_name:line.product_name,quantity:line.quantity}))}))} sales={data.sales.map(({product_name,quantity,paid_at,transferred_amount,net_profit})=>({product_name,quantity,paid_at,transferred_amount,net_profit}))} onStockChange={changeStockFromAI}/>}
 {tab==='settings'&&<div className="settings-layout"><section className="panel settings"><div className="settings-heading"><span className="settings-icon">Z</span><div><h2>Mağaza məlumatları</h2><p>Əlaqə məlumatlarını yenilə və yadda saxla.</p></div></div><form onSubmit={saveSettings}><label>Mağaza adı<input value={sett.store_name||'ZED STORE'} onChange={e=>SS({...sett,store_name:e.target.value})}/></label><label>Mağaza e-poçtu<input type="email" placeholder="info@zedstore.az" value={storeEmail} onChange={e=>SEmail(e.target.value)}/></label><label>Telefon nömrəsi<input type="tel" placeholder="+994 50 000 00 00" value={storePhone} onChange={e=>SPhone(e.target.value)}/></label><button className="primary">Məlumatları saxla</button></form><p className="settings-foot">Əlaqə məlumatları bu cihazda saxlanılır. Giriş hesabının e-poçtu: {user.email}</p></section><section className="panel settings password-panel"><div className="settings-heading"><span className="settings-icon">🔒</span><div><h2>Şifrəni dəyiş</h2><p>Hesabının yeni şifrəsini təyin et.</p></div></div><form onSubmit={changePassword}><label>Yeni şifrə<input type="password" minLength="8" autoComplete="new-password" required value={newPassword} onChange={e=>NP(e.target.value)} placeholder="Ən azı 8 simvol"/></label><label>Yeni şifrənin təkrarı<input type="password" minLength="8" autoComplete="new-password" required value={confirmPassword} onChange={e=>CP(e.target.value)} placeholder="Şifrəni yenidən yaz"/></label><button className="primary" disabled={passwordBusy}>{passwordBusy?'Yenilənir...':'Şifrəni yenilə'}</button></form><p className="settings-foot">Şifrə birbaşa təhlükəsiz hesab xidməti vasitəsilə yenilənir. Şifrənizi heç kimlə paylaşmayın.</p></section><section className="panel settings api-settings"><div className="settings-heading"><span className="settings-icon">AI</span><div><h2>ChatGPT bağlantısı</h2><p>ChatGPT-yə sifariş yaratmaq və statusları idarə etmək icazəsi ver.</p></div></div>{data.apiKey?<><div className="api-key-active"><b>● Bağlantı aktivdir</b><small>Yaradılma: {dt(data.apiKey.created_at)}</small>{data.apiKey.last_used_at&&<small>Son istifadə: {dt(data.apiKey.last_used_at)}</small>}</div>{apiKeyText&&<label>API açarı — yalnız indi görünür<textarea readOnly rows="3" value={apiKeyText}/><button type="button" className="outline" onClick={()=>{navigator.clipboard?.writeText(apiKeyText).then(()=>say("Açar kopyalandı")).catch(()=>say("Açarı seçib əl ilə kopyala"))}}>Açarı kopyala</button></label>}<button type="button" className="outline" onClick={revokeChatGPTKey}>Bağlantını ləğv et</button></>:<><p className="settings-foot">Açar yalnız bir dəfə göstəriləcək. Onu ChatGPT Action sazlamasında API Key kimi daxil edəcəksən.</p><button type="button" className="primary" disabled={apiKeyBusy} onClick={createChatGPTKey}>{apiKeyBusy?"Yaradılır...":"ChatGPT bağlantısı yarat"}</button></>}{apiKeyText&&<p className="settings-foot">Açar itərsə, bağlantını ləğv edib yenisini yarat.</p>}</section></div>}
